1: 'use strict';
2: 
3: import utils from '../utils.js';
4: import buildURL from '../helpers/buildURL.js';
5: import InterceptorManager from './InterceptorManager.js';
6: import dispatchRequest from './dispatchRequest.js';
7: import mergeConfig from './mergeConfig.js';
8: import buildFullPath from './buildFullPath.js';
9: import validator from '../helpers/validator.js';
10: import AxiosHeaders from './AxiosHeaders.js';
11: import transitionalDefaults from '../defaults/transitional.js';
12: 
13: const validators = validator.validators;
14: 
15: /**
16:  * Create a new instance of Axios
17:  *
18:  * @param {Object} instanceConfig The default config for the instance
19:  *
20:  * @return {Axios} A new instance of Axios
21:  */
22: class Axios {
23:   constructor(instanceConfig) {
24:     this.defaults = instanceConfig || {};
25:     this.interceptors = {
26:       request: new InterceptorManager(),
27:       response: new InterceptorManager(),
28:     };
29:   }
30: 
31:   /**
32:    * Dispatch a request
33:    *
34:    * @param {String|Object} configOrUrl The config specific for this request (merged with this.defaults)
35:    * @param {?Object} config
36:    *
37:    * @returns {Promise} The Promise to be fulfilled
38:    */
39:   async request(configOrUrl, config) {
40:     try {
41:       return await this._request(configOrUrl, config);
42:     } catch (err) {
43:       if (err instanceof Error) {
44:         let dummy = {};
45: 
46:         Error.captureStackTrace ? Error.captureStackTrace(dummy) : (dummy = new Error());
47: 
48:         // slice off the Error: ... line
49:         const stack = (() => {
50:           if (!dummy.stack) {
51:             return '';
52:           }
53: 
54:           const firstNewlineIndex = dummy.stack.indexOf('\n');
55: 
56:           return firstNewlineIndex === -1 ? '' : dummy.stack.slice(firstNewlineIndex + 1);
57:         })();
58:         try {
59:           if (!err.stack) {
60:             err.stack = stack;
61:             // match without the 2 top stack lines
62:           } else if (stack) {
63:             const firstNewlineIndex = stack.indexOf('\n');
64:             const secondNewlineIndex =
65:               firstNewlineIndex === -1 ? -1 : stack.indexOf('\n', firstNewlineIndex + 1);
66:             const stackWithoutTwoTopLines =
67:               secondNewlineIndex === -1 ? '' : stack.slice(secondNewlineIndex + 1);
68: 
69:             if (!String(err.stack).endsWith(stackWithoutTwoTopLines)) {
70:               err.stack += '\n' + stack;
71:             }
72:           }
73:         } catch (e) {
74:           // ignore the case where "stack" is an un-writable property
75:         }
76:       }
77: 
78:       throw err;
79:     }
80:   }
81: 
82:   _request(configOrUrl, config) {
83:     /*eslint no-param-reassign:0*/
84:     // Allow for axios('example/url'[, config]) a la fetch API
85:     if (typeof configOrUrl === 'string') {
86:       config = config || {};
87:       config.url = configOrUrl;
88:     } else {
89:       config = configOrUrl || {};
90:     }
91: 
92:     config = mergeConfig(this.defaults, config);
93: 
94:     const { transitional, paramsSerializer, headers } = config;
95: 
96:     if (transitional !== undefined) {
97:       validator.assertOptions(
98:         transitional,
99:         {
100:           silentJSONParsing: validators.transitional(validators.boolean),
101:           forcedJSONParsing: validators.transitional(validators.boolean),
102:           clarifyTimeoutError: validators.transitional(validators.boolean),
103:           legacyInterceptorReqResOrdering: validators.transitional(validators.boolean),
104:           advertiseZstdAcceptEncoding: validators.transitional(validators.boolean),
105:           validateStatusUndefinedResolves: validators.transitional(validators.boolean),
106:         },
107:         false
108:       );
109:     }
110: 
111:     if (paramsSerializer != null) {
112:       if (utils.isFunction(paramsSerializer)) {
113:         config.paramsSerializer = {
114:           serialize: paramsSerializer,
115:         };
116:       } else {
117:         validator.assertOptions(
118:           paramsSerializer,
119:           {
120:             encode: validators.function,
121:             serialize: validators.function,
122:           },
123:           true
124:         );
125:       }
126:     }
127: 
128:     // Set config.allowAbsoluteUrls
129:     if (config.allowAbsoluteUrls !== undefined) {
130:       // do nothing
131:     } else if (this.defaults.allowAbsoluteUrls !== undefined) {
132:       config.allowAbsoluteUrls = this.defaults.allowAbsoluteUrls;
133:     } else {
134:       config.allowAbsoluteUrls = true;
135:     }
136: 
137:     validator.assertOptions(
138:       config,
139:       {
140:         baseUrl: validators.spelling('baseURL'),
141:         withXsrfToken: validators.spelling('withXSRFToken'),
142:       },
143:       true
144:     );
145: 
146:     // Set config.method
147:     config.method = (config.method || this.defaults.method || 'get').toLowerCase();
148: 
149:     // Flatten headers
150:     let contextHeaders = headers && utils.merge(headers.common, headers[config.method]);
151: 
152:     headers &&
153:       utils.forEach(['delete', 'get', 'head', 'post', 'put', 'patch', 'query', 'common'], (method) => {
154:         delete headers[method];
155:       });
156: 
157:     config.headers = AxiosHeaders.concat(contextHeaders, headers);
158: 
159:     // filter out skipped interceptors
160:     const requestInterceptorChain = [];
161:     let synchronousRequestInterceptors = true;
162:     this.interceptors.request.forEach(function unshiftRequestInterceptors(interceptor) {
163:       if (typeof interceptor.runWhen === 'function' && interceptor.runWhen(config) === false) {
164:         return;
165:       }
166: 
167:       synchronousRequestInterceptors = synchronousRequestInterceptors && interceptor.synchronous;
168: 
169:       const transitional = config.transitional || transitionalDefaults;
170:       const legacyInterceptorReqResOrdering =
171:         transitional && transitional.legacyInterceptorReqResOrdering;
172: 
173:       if (legacyInterceptorReqResOrdering) {
174:         requestInterceptorChain.unshift(interceptor.fulfilled, interceptor.rejected);
175:       } else {
176:         requestInterceptorChain.push(interceptor.fulfilled, interceptor.rejected);
177:       }
178:     });
179: 
180:     const responseInterceptorChain = [];
181:     this.interceptors.response.forEach(function pushResponseInterceptors(interceptor) {
182:       responseInterceptorChain.push(interceptor.fulfilled, interceptor.rejected);
183:     });
184: 
185:     let promise;
186:     let i = 0;
187:     let len;
188: 
189:     if (!synchronousRequestInterceptors) {
190:       const chain = [dispatchRequest.bind(this), undefined];
191:       chain.unshift(...requestInterceptorChain);
192:       chain.push(...responseInterceptorChain);
193:       len = chain.length;
194: 
195:       promise = Promise.resolve(config);
196: 
197:       while (i < len) {
198:         promise = promise.then(chain[i++], chain[i++]);
199:       }
200: 
201:       return promise;
202:     }
203: 
204:     len = requestInterceptorChain.length;
205: 
206:     let newConfig = config;
207: 
208:     while (i < len) {
209:       const onFulfilled = requestInterceptorChain[i++];
210:       const onRejected = requestInterceptorChain[i++];
211:       try {
212:         newConfig = onFulfilled(newConfig);
213:       } catch (error) {
214:         onRejected.call(this, error);
215:         break;
216:       }
217:     }
218: 
219:     try {
220:       promise = dispatchRequest.call(this, newConfig);
221:     } catch (error) {
222:       return Promise.reject(error);
223:     }
224: 
225:     i = 0;
226:     len = responseInterceptorChain.length;
227: 
228:     while (i < len) {
229:       promise = promise.then(responseInterceptorChain[i++], responseInterceptorChain[i++]);
230:     }
231: 
232:     return promise;
233:   }
234: 
235:   getUri(config) {
236:     config = mergeConfig(this.defaults, config);
237:     const fullPath = buildFullPath(config.baseURL, config.url, config.allowAbsoluteUrls, config);
238:     return buildURL(fullPath, config.params, config.paramsSerializer);
239:   }
240: }
241: 
242: // Provide aliases for supported request methods
243: utils.forEach(['delete', 'get', 'head', 'options'], function forEachMethodNoData(method) {
244:   /*eslint func-names:0*/
245:   Axios.prototype[method] = function (url, config) {
246:     return this.request(
247:       mergeConfig(config || {}, {
248:         method,
249:         url,
250:         data: config && utils.hasOwnProp(config, 'data') ? config.data : undefined,
251:       })
252:     );
253:   };
254: });
255: 
256: utils.forEach(['post', 'put', 'patch', 'query'], function forEachMethodWithData(method) {
257:   function generateHTTPMethod(isForm) {
258:     return function httpMethod(url, data, config) {
259:       return this.request(
260:         mergeConfig(config || {}, {
261:           method,
262:           headers: isForm
263:             ? {
264:                 'Content-Type': 'multipart/form-data',
265:               }
266:             : {},
267:           url,
268:           data,
269:         })
270:       );
271:     };
272:   }
273: 
274:   Axios.prototype[method] = generateHTTPMethod();
275: 
276:   // QUERY is a safe/idempotent read method; multipart form bodies don't fit
277:   // its semantics, so no queryForm shorthand is generated.
278:   if (method !== 'query') {
279:     Axios.prototype[method + 'Form'] = generateHTTPMethod(true);
280:   }
281: });
282: 
283: export default Axios;
